'use strict';
const $=id=>document.getElementById(id),A=CandleAnalysis;
const assets=new Map();let selected=[],charts={},data=null,map=new Map(),available=[];
const pct=(a,b)=>b?100*a/b:null,show=n=>n==null?'—':n.toFixed(2)+'%',nfmt=n=>n.toLocaleString('en-US');
const fmt=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labelAsset=a=>a.symbol+(a.exchange?' · '+a.exchange:'');
function addFile(file){const asset=assets.get(file.id)||{id:file.id,symbol:file.symbol,exchange:file.exchange,files:{}};asset.files[file.minutes]=file;if(asset.legacy){delete asset.legacy[file.minutes===240?'H4':file.minutes===120?'H2':'unrelated'];}assets.set(file.id,asset);return asset;}
function loadAssets(){const current=$('asset').value;$('asset').replaceChildren(...[...assets.values()].map(a=>new Option(labelAsset(a),a.id)));if(assets.has(current))$('asset').value=current;}
function wilson(k,n){if(!n)return'—';const z=1.96,p=k/n,den=1+z*z/n,c=(p+z*z/(2*n))/den,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/den;return((c-h)*100).toFixed(1)+'–'+((c+h)*100).toFixed(1)+'%';}
function prepare(){
 const asset=assets.get($('asset').value);for(const opt of $('mode').options){const source=A.materialize(asset,opt.value,$('excludeLast').checked);opt.disabled=!source.rows.length;}
 if($('mode').selectedOptions[0].disabled)$('mode').value=[...$('mode').options].find(o=>!o.disabled)?.value||'H4';
 data=A.materialize(asset,$('mode').value,$('excludeLast').checked);map=A.dayMap(data.rows);available=[...new Set(data.rows.map(r=>r.minute))].sort((a,b)=>a-b);
 const years=[...new Set(data.rows.map(r=>r.date.slice(0,4)))].sort(),oldYear=$('year').value;
 $('year').replaceChildren(new Option('ทุกปีในข้อมูล','all'),...years.map(y=>new Option(y,y)));if(years.includes(oldYear))$('year').value=oldYear;
 for(const id of ['from','to'])$(id).replaceChildren(...available.map(m=>new Option(fmt(m),m)));
 if(available.length>1)$('to').value=available[1];
 const presets=$('mode').value==='H4'?[[60,300],[60,540],[300,540],[540,780]]:[[60,300],[300,540],[60,540],[540,660],[660,780],[540,780]];
 selected=presets.filter(p=>p.every(m=>available.includes(m)));if(!selected.length&&available.length>1)selected=available.slice(0,-1).slice(0,4).map((x,i)=>[x,available[i+1]]);
 if(selected.length){$('from').value=selected[0][0];$('to').value=selected[0][1];}
 $('heading').textContent=asset.symbol+' Multi-Candle Comparison';document.title='Mr.Z | '+asset.symbol+' Multi-Candle Lab';
 const sorted=data.rows.map(r=>r.date).sort();$('scope').textContent=`${labelAsset(asset)} · ${data.method} · เวลาไทย (Asia/Bangkok) · ${sorted[0]||'—'} ถึง ${sorted.at(-1)||'—'}`;
 $('modeNote').textContent=`${data.method} • เวลาเปิดจริงที่พบ: ${available.map(fmt).join(', ')} • จับคู่ในวันไทยเดียวกันและใช้เฉพาะวันที่มีทั้งสองแท่ง; ไม่เลื่อนแท่งให้ตรงเวลาที่ไม่มีในไฟล์`;
 const f=data.file;const quality=f?`${f.name} · ${f.inputRows.toLocaleString()} แถว · แท่งไม่ซ้ำ ${f.candles.length.toLocaleString()} · แถวซ้ำเหมือนกัน ${f.duplicates} · ${$('excludeLast').checked?'ไม่นับแท่งท้ายสุด 1 แท่ง':'รวมแท่งท้ายสุด (ผู้ใช้ยืนยันแล้ว)'} · ${data.rows.length.toLocaleString()} แท่งที่ใช้ได้`:'ตาราง NQ1! เดิม: เก็บเฉพาะวัน เวลา และสีแท่งที่คำนวณไว้ ไม่มี OHLC ดิบ; ตัวเลือกตัดแท่งท้ายสุดใช้กับ CSV เท่านั้น';
 $('sourceText').textContent=quality;$('excludeLast').disabled=!f;
 $('sourceHours').textContent=available.map(m=>`${fmt(m)}: ${data.rows.filter(r=>r.minute===m).length.toLocaleString()} แท่ง`).join(' · ');
 render();
}
function addPair(a,b){if(a===b)return;if(!selected.some(x=>x[0]===a&&x[1]===b))selected.push([a,b]);render();}
function draw(id,type,labels,datasets,extra={}){
 if(charts[id])charts[id].destroy();
 Chart.defaults.color='#a9bdd3';Chart.defaults.borderColor='#26394c';
 charts[id]=new Chart($(id),{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom',labels:{usePointStyle:true,padding:18}},tooltip:{backgroundColor:'#15263c',padding:12,callbacks:{label:ctx=>`${ctx.dataset.label}: ${ctx.parsed.y==null?'ไม่มีข้อมูล':ctx.parsed.y.toFixed(2)+(extra.count?'':'%')}${ctx.dataset.samples?' · n='+ctx.dataset.samples[ctx.dataIndex]:''}`}}},scales:{x:{grid:{display:false},ticks:{maxRotation:0,autoSkip:true}},y:extra.count?{beginAtZero:true}:{min:0,max:100,ticks:{callback:v=>v+'%'}}}}});
}
function render(){
 const year=$('year').value,colors=['#35d7a2','#73a8ff','#f0c06b','#c49eff','#ff7589','#68d6e6','#f58ab8','#8ce084'];
 const pairs=[[60,300],[120,360],[300,540],[360,600],[60,540],[120,600],[540,660],[660,780],[540,780],[600,840]];
 $('presets').innerHTML='<span style="color:#9eb1c8;padding:10px">คู่ตัวอย่าง:</span>'+pairs.filter(p=>p.every(m=>available.includes(m))).map(([a,b])=>`<button class="chip" data-a="${a}" data-b="${b}">${fmt(a)} / ${fmt(b)}</button>`).join('');
 document.querySelectorAll('#presets button').forEach(btn=>btn.onclick=()=>addPair(+btn.dataset.a,+btn.dataset.b));
 $('pairs').innerHTML=selected.map(([a,b],i)=>`<button class="chip active" data-i="${i}">${fmt(a)} → ${fmt(b)} ✕</button>`).join('');
 document.querySelectorAll('#pairs button').forEach(btn=>btn.onclick=()=>{selected.splice(+btn.dataset.i,1);render();});
 const stat=(a,b,y=year,m=null)=>A.stats(map,a,b,y,m);
 const all=selected.map(([a,b])=>({...stat(a,b),label:fmt(a)+' → '+fmt(b),a,b}));
 const total=all.reduce((s,x)=>s+x.n,0),same=all.reduce((s,x)=>s+x.k,0);
 $('total').textContent=nfmt(total);$('same').textContent=show(pct(same,total));$('diff').textContent=show(pct(total-same,total));
 const valid=all.filter(x=>x.n>0).sort((a,b)=>b.rate-a.rate);$('best').textContent=valid.length?valid[0].label:'—';$('bestdetail').textContent=valid.length?show(valid[0].rate)+' · n='+valid[0].n:'ไม่มีข้อมูล';
 const labels=all.map(x=>x.label);
 draw('mainChart','bar',labels,[{label:'สีตรงกัน',data:all.map(x=>x.rate),backgroundColor:'#35d7a2',borderRadius:6,samples:all.map(x=>x.n)},{label:'สีไม่ตรงกัน',data:all.map(x=>x.n?100-x.rate:null),backgroundColor:'#ff7589',borderRadius:6,samples:all.map(x=>x.n)}]);
 draw('condChart','bar',labels,[{label:'เขียว → เขียว',data:all.map(x=>pct(x.gg,x.green)),backgroundColor:'#35d7a2',borderRadius:6,samples:all.map(x=>x.green)},{label:'แดง → แดง',data:all.map(x=>pct(x.rr,x.red)),backgroundColor:'#73a8ff',borderRadius:6,samples:all.map(x=>x.red)}]);
 draw('countChart','bar',labels,[{label:'จำนวนคู่',data:all.map(x=>x.n),backgroundColor:'#73a8ff',borderRadius:6}],{count:true});
 const years=year==='all'?[...new Set(data.rows.map(r=>r.date.slice(0,4)))].sort():[year];
 draw('yearChart','line',years,selected.map(([a,b],i)=>({label:fmt(a)+' / '+fmt(b),data:years.map(y=>stat(a,b,y).rate),samples:years.map(y=>stat(a,b,y).n),borderColor:colors[i%colors.length],backgroundColor:colors[i%colors.length],tension:.28,spanGaps:false})));
 const months=Array.from({length:12},(_,i)=>i+1);
 draw('monthChart','line',months.map(x=>['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][x-1]),selected.map(([a,b],i)=>({label:fmt(a)+' / '+fmt(b),data:months.map(m=>stat(a,b,year,m).rate),samples:months.map(m=>stat(a,b,year,m).n),borderColor:colors[i%colors.length],backgroundColor:colors[i%colors.length],tension:.25,spanGaps:false})));
 $('table').innerHTML=all.map(x=>`<tr><td>${x.label}</td><td>${nfmt(x.n)}</td><td>${x.k}</td><td>${x.n-x.k}</td><td>${show(x.rate)}</td><td>${show(pct(x.gg,x.green))} (n=${x.green})</td><td>${show(pct(x.rr,x.red))} (n=${x.red})</td><td>${wilson(x.k,x.n)}</td></tr>`).join('')||'<tr><td colspan="8">กรุณาเลือกคู่เปรียบเทียบ</td></tr>';
}
const legacy={id:'CME_MINI:NQ1!',symbol:'NQ1!',exchange:'CME_MINI',files:{},legacy:{H4:[],H2:[]}};
for(const [date,mode,hour,colour] of LEGACY_NQ)legacy.legacy[mode===0?'H4':'H2'].push({date,minute:hour*60,colour});
assets.set(legacy.id,legacy);const gold=addFile(A.ingest(GOLD_CSV,GOLD_FILENAME));loadAssets();$('asset').value=gold.id;
async function importFiles(input){const files=[...input];if(!files.length)return;const errors=[];const loaded=[];let chosen=null;
 $('fileStatus').textContent='กำลังอ่านไฟล์…';
 for(const f of files){try{const file=A.ingest(await f.text(),f.name);chosen=addFile(file).id;loaded.push(f.name);}catch(e){errors.push(f.name+': '+e.message);}}
 loadAssets();if(chosen){$('asset').value=chosen;$('year').value='all';$('mode').value='H4';prepare();}
 $('fileStatus').textContent=[loaded.length?`โหลดแล้ว ${loaded.length} ไฟล์: ${loaded.join(' • ')}`:'',...errors].filter(Boolean).join(' • ');}
$('files').onchange=event=>importFiles(event.target.files);
$('files').onclick=event=>{event.target.value='';};
const drop=$('dropZone');
for(const name of ['dragenter','dragover'])drop.addEventListener(name,event=>{event.preventDefault();drop.classList.add('dragging');});
for(const name of ['dragleave','drop'])drop.addEventListener(name,event=>{event.preventDefault();drop.classList.remove('dragging');});
drop.addEventListener('drop',event=>importFiles(event.dataTransfer.files));
$('asset').onchange=()=>{$('year').value='all';prepare();};$('mode').onchange=prepare;$('excludeLast').onchange=prepare;$('year').onchange=render;
$('add').onclick=()=>addPair(+$('from').value,+$('to').value);$('clear').onclick=()=>{selected=[];render();};prepare();

